/* ---------- geometri ---------- */
function schPip(P,x,y){let c=false;for(let i=0,j=P.length-1;i<P.length;j=i++){const a=P[i],b=P[j];if((a[1]>y)!==(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])c=!c;}return c;}
function schSeg(P,x,y,closed){let best=1e18,st=0,acc=0,bs=0;const n=P.length;for(let i=0;i<n-(closed?0:1);i++){const a=P[i],b=P[(i+1)%n],dx=b[0]-a[0],dy=b[1]-a[1],L=Math.hypot(dx,dy)||1e-9;let u=((x-a[0])*dx+(y-a[1])*dy)/(L*L);u=Math.max(0,Math.min(1,u));const d=Math.hypot(a[0]+dx*u-x,a[1]+dy*u-y);if(d<best){best=d;bs=acc+u*L;}acc+=L;}return [best,bs,acc];}
/* preset alat angkut: payload t, bak m³ (heaped), kecepatan bermuatan / kosong km/jam (rata-rata jalan tambang) */
const SCHH=[['dt20','Dump truck 6×4 (±20 t)',20,14,20,30],['adt40','Articulated DT 40 t',39,24,22,35],['r60','Rigid DT 60 t (HD465)',55,34,22,36],['r90','Rigid DT 90 t (HD785)',91,60,22,38],['r100','Rigid DT 100 t (CAT 777)',98,64,22,40]];
function schRL(P){let L=0;for(let i=1;i<P.length;i++)L+=Math.hypot(P[i][0]-P[i-1][0],P[i][1]-P[i-1][1],P[i][2]-P[i-1][2]);return L;}
/* siklus truk untuk muat di sel c pada elevasi zc: jarak (keluar pit lewat ramp + jalur angkut), waktu muat, siklus, kebutuhan DT */
function schHaul(t,Gd,c,zc){const sg=Math.max(0.01,+$('schsg').value||2.5),rl=sg/(1+(t.sw||0)/100),ld=Math.min(t.hp,t.hv*rl),lcm=ld/rl,bcm=ld/sg;
 const lt=t.pm2==='bkt'&&t.bkt>0&&t.cyc>0?Math.ceil(lcm/(t.bkt*t.ff)-1e-9)*t.cyc/60:bcm/Math.max(1e-6,schPrd(t))*60,ps=t.pm2==='bkt'&&t.bkt>0?Math.ceil(lcm/(t.bkt*t.ff)-1e-9):0,g=Math.max(1,t.hg||8)/100;let d;
 const x=Gd.cx[c],y=Gd.cy[c];if(t.hr&&t.hr.length>1){const a=t.hr[0],hz=Math.hypot(a[0]-x,a[1]-y)*(t.hf||1.15),dz=Math.abs(a[2]-zc);d=Math.max(hz,dz/g)+schRL(t.hr);}else d=(t.hd||0)+Math.max(0,Gd.z0[c]-zc)/g;
 const hl=d/1000/Math.max(1,t.vl)*60,rt=d/1000/Math.max(1,t.ve)*60,ct=lt+(t.ts||0)+hl+(t.td||0)+rt,nu=Math.max(1,t.nu|0),need=Math.ceil(nu*ct/lt-1e-6),f=t.hn>0?Math.min(1,t.hn*lt/(nu*ct)):1;
 return {d,lt,ct,need,f,ps,ld,bcm,tph:bcm*60/ct};}
function schHtxt(t){try{const sg=Math.max(0.01,+$('schsg').value||2.5),rl=sg/(1+(t.sw||0)/100),ld=Math.min(t.hp,t.hv*rl),bcm=ld/sg,ps=t.pm2==='bkt'&&t.bkt>0?Math.ceil(ld/rl/(t.bkt*t.ff)-1e-9):0,lt=ps?ps*t.cyc/60:bcm/Math.max(1e-6,schPrd(t))*60,d=t.hr?schRL(t.hr):(t.hd||0),ct=lt+(t.ts||0)+(t.td||0)+d/1000*60*(1/Math.max(1,t.vl)+1/Math.max(1,t.ve));
 return '&#128666; '+schF(bcm,1)+' BCM/rit'+(ps?' ('+ps+' pass)':'')+' · siklus '+schF(ct,1)+' mnt → <b>'+Math.ceil(Math.max(1,t.nu|0)*ct/lt-1e-6)+' DT</b> <span style="color:#868e96">(dihitung ulang tiap shift + ramp)</span>';}catch(_){return '';}}
function schPrd(t){/* produktivitas per unit, BCM/jam */const sg=Math.max(0.01,+$('schsg').value||2.5);if(t.pm2==='bkt'){if(!(t.cyc>0))return 0;return t.bkt*t.ff*(3600/t.cyc)*t.eff/(1+t.sw/100);}return t.prod/(t.unit==='tonh'?sg:1);}
function schEj(t){/* jam efektif per shift = jam jadwal × PA × UA */return Math.max(0,t.sch)*Math.max(0,t.pa)/100*Math.max(0,t.ua)/100;}
function schCap(t){return Math.max(1,t.nu|0)*schPrd(t)*schEj(t);}
function schGridFit(){const T=SCH.tasks.filter(t=>t.on);const bd=schPh().bnd;if(bd)T.push({type:'poly',pts:bd});if(!T.length)throw new Error('Belum ada batas fase / jalur gali.');const bx=+$('schbx').value,by=+$('schby').value,mg=Math.max(0,+$('schmg').value||0),az=(+$('schaz').value||0)*Math.PI/180;
 if(!(bx>0&&by>0))throw new Error('Ukuran blok harus > 0.');const ux=Math.sin(az),uy=Math.cos(az),vx=-uy,vy=ux;let s0=1e18,s1=-1e18,t0=1e18,t1=-1e18;
 for(const t of T){const pad=mg+(t.type!=='poly'?(t.wm!=='m'?(Math.max(1,t.nb|0)+1)*Math.max(bx,by):t.w/2):0);for(const p of t.pts){const s=p[0]*ux+p[1]*uy,q=p[0]*vx+p[1]*vy;s0=Math.min(s0,s-pad);s1=Math.max(s1,s+pad);t0=Math.min(t0,q-pad);t1=Math.max(t1,q+pad);}}
 s0=Math.floor(s0/bx)*bx;t0=Math.floor(t0/by)*by;const nx=Math.ceil((s1-s0)/bx),ny=Math.ceil((t1-t0)/by);if(nx*ny>400000)throw new Error('Grid terlalu besar ('+nx+' × '+ny+' blok). Perbesar ukuran blok atau perkecil area.');
 const n=nx*ny,cx=new Float64Array(n),cy=new Float64Array(n),z0=new Float32Array(n);for(let j=0;j<ny;j++)for(let i=0;i<nx;i++){const k=j*nx+i,s=s0+(i+.5)*bx,q=t0+(j+.5)*by;cx[k]=s*ux+q*vx;cy[k]=s*uy+q*vy;z0[k]=topoZ(cx[k],cy[k]);}
 SCH.grid={bx,by,az,ux,uy,vx,vy,s0,t0,nx,ny,cx,cy,z0,h:Math.max(0.1,+$('schh2').value||2.5)};return SCH.grid;}
/* blok AOI yang dilewati garis A→B (supercover per sub-langkah), dilebarkan (nb−1)/2 blok ke kiri-kanan */
function schPathMask(Gd,P,nb){const {nx,ny}=Gd,m=new Uint8Array(nx*ny),st=Math.min(Gd.bx,Gd.by)/8,hw=Math.max(1,nb)/2,ri=Math.ceil(hw)+1;
 const mark=(x,y)=>{const fs=(x*Gd.ux+y*Gd.uy-Gd.s0)/Gd.bx,fq=(x*Gd.vx+y*Gd.vy-Gd.t0)/Gd.by,i=Math.floor(fs),j=Math.floor(fq);for(let dj=-ri;dj<=ri;dj++)for(let di=-ri;di<=ri;di++){const a=i+di,b=j+dj;if(Math.abs(a+.5-fs)>hw||Math.abs(b+.5-fq)>hw)continue;if(a>=0&&b>=0&&a<nx&&b<ny)m[b*nx+a]=1;}};
 for(let k=0;k+1<P.length;k++){const a=P[k],b=P[k+1],L=Math.hypot(b[0]-a[0],b[1]-a[1]),n=Math.max(1,Math.ceil(L/st));for(let u=0;u<=n;u++)mark(a[0]+(b[0]-a[0])*u/n,a[1]+(b[1]-a[1])*u/n);}return m;}
